  function backupImport(refresh){var input=h('input.input',{type:'file',accept:'.json,application/json','aria-label':'Selecionar cópia de segurança'}),error=h('div.fw-form-error',{role:'alert',hidden:true}),api,busy=false;var submit=btn('Restaurar dados',async function(){if(busy)return;if(!input.files||!input.files[0]){error.hidden=false;error.textContent='Selecione um arquivo JSON.';return;}if(!await UI.confirm({title:'Substituir os dados financeiros?',text:'A cópia selecionada substituirá os dados financeiros atuais. Exporte sua cópia atual antes de continuar.',danger:true,okLabel:'Restaurar cópia'}))return;busy=true;submit.disabled=true;try{var state=JSON.parse(await input.files[0].text());await fin().command('backup.import',{state:state});UI.toast.ok('Cópia restaurada');api.close();refresh();}catch(e){error.hidden=false;error.textContent=e.message;}finally{busy=false;submit.disabled=false;}},true);api=UI.modal({title:'Restaurar cópia de segurança',sub:'Importe somente uma cópia financeira exportada por este sistema.',body:h('div',input,error),footer:function(m){return [btn('Cancelar',function(){if(!busy)m.close();}),submit];}});}
